	('e8550754-f65e-4957-ae86-cc1f8e3de113', '00000000-0000-0000-0000-000000000001', 'feature_tip', 'Welcome to MTAA OS', 'Discover all-in-one African super app. Wallet, transport, marketplace, governance, education — all in one place.', NULL, NULL, 'all', 'new_users', 5, true, '2026-06-16 14:05:51.398666+00', NULL, NULL, 0, 0, '2026-06-16 14:05:51.398666+00', '2026-06-16 14:05:51.398666+00'),
	('dc6273bb-164b-4ca2-9068-a7b147b95d27', '00000000-0000-0000-0000-000000000001', 'advert', 'MTaxi: Ride Anywhere', 'Book safe rides across Africa. Drivers are verified, fares are fair, and you pay with your MTAA Wallet.', NULL, NULL, 'mtaxi', 'all', 4, true, '2026-06-16 14:05:51.398666+00', NULL, NULL, 0, 0, '2026-06-16 14:05:51.398666+00', '2026-06-16 14:05:51.398666+00'),
	('266ede91-54be-438b-8bc1-62073b39aea5', '00000000-0000-0000-0000-000000000001', 'advert', 'MTruck: Move Anything', 'From parcels to pallets, MTruck connects you with verified truck drivers. Real-time tracking, escrow payments.', NULL, NULL, 'mtruck', 'all', 4, true, '2026-06-16 14:05:51.398666+00', NULL, NULL, 0, 0, '2026-06-16 14:05:51.398666+00', '2026-06-16 14:05:51.398666+00'),
	('b354ba3c-9941-4d33-b87b-1356fac260f1', '00000000-0000-0000-0000-000000000001', 'feature_tip', 'Your MTAA Wallet', 'Send, receive, deposit, and withdraw with KES. Secure PIN protection, biometric login, and instant transfers.', NULL, NULL, 'wallet', 'all', 5, true, '2026-06-16 14:05:51.398666+00', NULL, NULL, 0, 0, '2026-06-16 14:05:51.398666+00', '2026-06-16 14:05:51.398666+00'),
	('e05ea840-e600-4efd-af9f-10b2c4a1bc02', '00000000-0000-0000-0000-000000000001', 'advert', 'MTAA Marketplace', 'Buy and sell anything. From electronics to farm produce. Verified sellers, escrow protection, and delivery tracking.', NULL, NULL, 'marketplace', 'all', 3, true, '2026-06-16 14:05:51.398666+00', NULL, NULL, 0, 0, '2026-06-16 14:05:51.398666+00', '2026-06-16 14:05:51.398666+00'),
	('51f40cf6-051c-4206-a9fd-a2b5ea8c0eed', '00000000-0000-0000-0000-000000000001', 'feature_tip', 'Governance & Civic', 'Participate in your community. Report issues, vote on projects, track government spending. Your voice matters.', NULL, NULL, 'civic', 'all', 4, true, '2026-06-16 14:05:51.398666+00', NULL, NULL, 0, 0, '2026-06-16 14:05:51.398666+00', '2026-06-16 14:05:51.398666+00'),
	('d02e5415-43fe-4b8e-8859-094c51968a20', '00000000-0000-0000-0000-000000000001', 'advert', 'MTAA Education', 'Learn new skills, find tutors, manage schools. From nursery to university — education for every African.', NULL, NULL, 'education', 'all', 3, true, '2026-06-16 14:05:51.398666+00', NULL, NULL, 0, 0, '2026-06-16 14:05:51.398666+00', '2026-06-16 14:05:51.398666+00'),
	('4d042624-2fb1-46f1-ab77-9672a0cbf72a', '00000000-0000-0000-0000-000000000001', 'feature_tip', 'Content & Creator Tools', 'Share videos, photos, and stories. Build your audience, monetize your content, and earn badges.', NULL, NULL, 'content', 'creators', 4, true, '2026-06-16 14:05:51.398666+00', NULL, NULL, 0, 0, '2026-06-16 14:05:51.398666+00', '2026-06-16 14:05:51.398666+00'),
	('a29b3ca1-b4f9-48c9-972a-7543b83b4923', '00000000-0000-0000-0000-000000000001', 'announcement', 'Trust Score Explained', 'Complete KYC, verify your identity, and build your trust score. Higher score = more features, lower fees, better deals.', NULL, NULL, 'all', 'all', 5, true, '2026-06-16 14:05:51.398666+00', NULL, NULL, 0, 0, '2026-06-16 14:05:51.398666+00', '2026-06-16 14:05:51.398666+00'),
	('c0e33425-fdef-474a-ac35-a50b6443b575', '00000000-0000-0000-0000-000000000001', 'tutorial', 'How to Add a Business', 'Set up your business profile in minutes. Add products, manage orders, and accept MTAA Wallet payments.', NULL, NULL, 'marketplace', 'sellers', 3, true, '2026-06-16 14:05:51.398666+00', NULL, NULL, 0, 0, '2026-06-16 14:05:51.398666+00', '2026-06-16 14:05:51.398666+00');


